package aulas.umc.oo.controller; import aulas.umc.oo.DTO.*; import aulas.umc.oo.UseCase.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/pagamentos") public class PagamentoController { private final PagamentoUseCase crud; private final ProcessoPedidoUseCase proc; public PagamentoController(PagamentoUseCase c,ProcessoPedidoUseCase p){crud=c;proc=p;} @PostMapping public PagamentoResponse criar(@Valid @RequestBody PagamentoRequest r){return crud.criar(r);} @GetMapping public List<PagamentoResponse> listar(){return crud.listar();} @GetMapping("/{id}") public PagamentoResponse buscar(@PathVariable UUID id){return crud.buscar(id);} @PutMapping("/{id}") public PagamentoResponse atualizar(@PathVariable UUID id,@Valid @RequestBody PagamentoRequest r){return crud.atualizar(id,r);} @DeleteMapping("/{id}") public void excluir(@PathVariable UUID id){crud.excluir(id);} @PostMapping("/{id}/processos/aprovar") public PipelineResponse aprovar(@PathVariable UUID id){return proc.aprovarPagamento(id);} @PostMapping("/{id}/processos/estornar") public PipelineResponse estornar(@PathVariable UUID id){return proc.estornarPagamento(id);} }
